package com.example.waterpolo3000.data

import androidx.room.*
import kotlinx.coroutines.flow.Flow

@Dao
interface GameEventDao {
    /*
    * GameFragment queries
    * */
    @Query("SELECT * FROM (SELECT team.teamName AS firstName, team.teamLocation AS lastName, gameEvent.guid, gameEvent.time, gameEvent.gameEventType, gameEventTypes.name AS gameEventTypeString, CAST(gameEvent.gameSection AS text) AS gameSection,\"\" as number, participant.cap FROM gameEvent INNER JOIN participant ON gameEvent.participant=participant.guid INNER JOIN gameEventTypes ON gameEvent.gameEventType=gameEventTypes.id INNER JOIN team ON participant.team=team.guid WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND gameEvent.gameEventType=9 AND gameEvent.deleted=0 AND participant.deleted=0) UNION ALL SELECT * FROM (SELECT D.playerFirstName AS firstName,D.playerLastName AS lastName, A.guid AS guid,A.time,A.gameEventType AS gameEventType,C.name AS gameEventTypeString,CAST(A.gameSection AS text) AS gameSection,CAST(B.number AS text) AS number, B.cap AS cap FROM gameEvent A INNER JOIN participant B ON A.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND A.participant=B.guid INNER JOIN gameEventTypes C ON A.gameEventType=C.id INNER JOIN player D ON B.player=D.guid WHERE A.deleted=0 AND B.deleted=0 AND D.deleted=0) ORDER BY gameSection DESC, time ASC")
    fun getAllGameEventPlayer(): Flow<List<GameEventView>>

    @Query("SELECT * FROM (SELECT team.teamName AS firstName, team.teamLocation AS lastName, gameEvent.guid, gameEvent.time, gameEvent.gameEventType, gameEventTypes.name AS gameEventTypeString, CAST(gameEvent.gameSection AS text) AS gameSection,\"\" as number, participant.cap FROM gameEvent INNER JOIN participant ON gameEvent.participant=participant.guid INNER JOIN gameEventTypes ON gameEvent.gameEventType=gameEventTypes.id INNER JOIN team ON participant.team=team.guid WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND gameEvent.gameEventType=9 AND gameEvent.deleted=0 AND participant.deleted=0 AND gameEvent.guid IN (:guids)) UNION ALL SELECT * FROM (SELECT D.playerFirstName AS firstName,D.playerLastName AS lastName, A.guid AS guid,A.time,A.gameEventType AS gameEventType,C.name AS gameEventTypeString,CAST(A.gameSection AS text) AS gameSection,CAST(B.number AS text) AS number, B.cap AS cap FROM gameEvent A INNER JOIN participant B ON A.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND A.participant=B.guid INNER JOIN gameEventTypes C ON A.gameEventType=C.id INNER JOIN player D ON B.player=D.guid WHERE A.deleted=0 AND B.deleted=0 AND D.deleted=0 AND A.guid IN (:guids)) ORDER BY gameSection DESC, time ASC")
    fun getAllGameEventPlayerByGuid(guids: List<String>): List<GameEventView>

    @Query("SELECT COUNT(*) AS count  FROM gameEvent INNER JOIN participant ON gameEvent.participant=participant.guid WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND gameEventType=9 AND participant.cap=:cap AND gameEvent.deleted=0 AND participant.deleted=0")
    fun getTimeout(cap: String): Flow<TimeoutCount>

    @Query("SELECT * FROM gameEvent")
    fun getAll(): Flow<List<GameEvent>>

    @Query("SELECT * FROM gameEvent WHERE guid=:guid")
    fun getGameEvent(guid: String): Flow<GameEvent>

    @Query("SELECT * FROM gameEvent WHERE game=:gameGuid")
    suspend fun getAllByGameGuidDirect(gameGuid: String): List<GameEvent>

    @Query("SELECT COUNT(*) FROM gameEvent")
    fun getCount(): Int

    @Query(
        "SELECT COUNT(*) FROM gameEvent INNER JOIN participant ON gameEvent.participant=participant.guid WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND gameEvent.gameSection=:gameSection AND gameEvent.deleted=0 AND participant.deleted=0 AND (gameEvent.gameEventType=9 OR participant.number>0)"
    )
    suspend fun getVisibleLogLineCountBySection(gameSection: Int): Int

    /*
    * */
    @Insert
    suspend fun insertAll(gameEvents: List<GameEvent>)

    @Insert
    suspend fun insert(gameEvent: GameEvent)

    @Query("UPDATE gameEvent SET deleted=1, lastUpdated=:lastUpdated WHERE gameEvent.guid=:guid")
    suspend fun updateToDelete(guid: String, lastUpdated: Long)

    @Query("UPDATE gameEvent SET deleted=1, lastUpdated=:lastUpdated WHERE game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND gameSection=:gameSection AND deleted=0")
    suspend fun updateToDeleteBySection(gameSection: Int, lastUpdated: Long): Int

    /*
        ProtocolFragment queries
    */
    @Query(
        "SELECT :cap AS cap, CAST(number as text) number,playerFirstName,playerLastName,'' AS playerId,COALESCE(P1,\"\") P1,COALESCE(P2,\"\") P2,COALESCE(P3,\"\") P3,CAST(tore AS text) tore FROM (SELECT number, MIN(playerFirstName) playerFirstName,MIN(playerLastName) playerLastName,MIN(p1) P1,MIN(p2) P2,MIN(p3) P3,MIN(tore) tore FROM (SELECT number, null playerFirstName,null playerLastName, MIN(p1) p1,MIN(p2) p2,MIN(p3) p3,null tore FROM (SELECT (CASE WHEN p.number IN (SELECT number FROM gameEvent INNER JOIN participant ON gameEvent.participant=participant.guid WHERE gameEventType>=:exclTypeMin AND gameEventType<=:exclTypeMax AND gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND participant.cap=:cap AND gameEvent.deleted=0 AND participant.deleted=0 AND participant.number>0 GROUP BY participant.number) THEN (SELECT nameShort FROM gameEvent INNER JOIN participant pp ON gameEvent.participant=pp.guid INNER JOIN gameEventTypes ON gameEventTypes.id>=:exclTypeMin AND gameEventTypes.id<=:exclTypeMax AND gameEvent.gameEventType=gameEventTypes.id WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND p.number=pp.number AND gameEvent.deleted=0 AND pp.deleted=0 AND p.number>0 AND pp.number>0 LIMIT 1) ELSE null END) p1,null p2,null p3,p.number FROM gameEvent INNER JOIN participant p ON gameEvent.participant=p.guid WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND p.cap=:cap AND gameEvent.deleted=0 AND p.deleted=0 AND p.number>0 GROUP BY p.number UNION ALL SELECT null p1,(CASE WHEN p.number IN (SELECT number FROM (SELECT Count(*) Count, number FROM gameEvent INNER JOIN participant ON gameEvent.participant=participant.guid WHERE gameEventType>=:exclTypeMin AND gameEventType<=:exclTypeMax AND gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND participant.cap=:cap AND gameEvent.deleted=0 AND participant.deleted=0 AND participant.number>0 GROUP BY participant.number) WHERE count>1) THEN (SELECT nameShort FROM gameEvent INNER JOIN participant pp ON gameEvent.participant=pp.guid INNER JOIN gameEventTypes ON gameEventTypes.id>=:exclTypeMin AND gameEventTypes.id<=:exclTypeMax AND  gameEvent.gameEventType=gameEventTypes.id WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND p.number=pp.number AND gameEvent.deleted=0 AND pp.deleted=0 AND p.number>0 AND pp.number>0 LIMIT 1 OFFSET 1) ELSE null END) p2,null p3,p.number FROM gameEvent INNER JOIN participant p ON gameEvent.participant=p.guid INNER JOIN gameEventTypes ON gameEvent.gameEventType=gameEventTypes.id WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND p.cap=:cap AND gameEventTypes.id>=:exclTypeMin AND gameEventTypes.id<=:exclTypeMax AND gameEvent.deleted=0 AND p.deleted=0 AND p.number>0 GROUP BY p.number UNION ALL SELECT null p1,null p2,(CASE WHEN p.number IN (SELECT number FROM (SELECT Count(*) Count, number FROM gameEvent INNER JOIN participant ON gameEvent.participant=participant.guid WHERE gameEventType>=:exclTypeMin AND gameEventType<=:exclTypeMax AND gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND participant.cap=:cap AND gameEvent.deleted=0 AND participant.deleted=0 AND participant.number>0 GROUP BY participant.number) WHERE count>2) THEN (SELECT nameShort FROM gameEvent INNER JOIN participant pp ON gameEvent.participant=pp.guid INNER JOIN gameEventTypes ON gameEventTypes.id>=:exclTypeMin AND gameEventTypes.id<=:exclTypeMax AND gameEvent.gameEventType=gameEventTypes.id WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND p.number=pp.number AND gameEvent.deleted=0 AND pp.deleted=0 AND p.number>0 AND pp.number>0 LIMIT 1 OFFSET 2) ELSE null END) p3,p.number FROM gameEvent INNER JOIN participant p ON gameEvent.participant=p.guid INNER JOIN gameEventTypes ON gameEvent.gameEventType=gameEventTypes.id WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND p.cap=:cap AND gameEventTypes.id>=:exclTypeMin AND gameEventTypes.id<=:exclTypeMax AND gameEvent.deleted=0 AND p.deleted=0 AND p.number>0 GROUP BY p.number) GROUP BY number UNION ALL SELECT participant.number,player.playerFirstName,player.playerLastName,null P1,null P2,null P3,SUM(CASE WHEN gameEvent.gameEventType<=:goalTypeMax AND gameEvent.gameEventType>=:goalTypeMin AND gameEvent.deleted=0 THEN 1 ELSE 0 END) AS tore FROM participant LEFT JOIN gameEvent ON participant.guid=gameEvent.participant INNER JOIN player ON player.guid=participant.player LEFT JOIN gameEventTypes ON gameEventTypes.id=gameEvent.gameEventType WHERE participant.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND participant.cap=:cap AND participant.number>0 GROUP BY participant.guid) GROUP BY number)"
    )
    fun getProtocolTeam(cap: String, exclTypeMin: Int, exclTypeMax: Int, goalTypeMin: Int, goalTypeMax: Int): Flow<List<ProtocolTeam>>

    @Query(
        "SELECT :cap AS cap, CAST(p.number AS text) AS number, pl.playerFirstName AS playerFirstName, pl.playerLastName AS playerLastName, CAST(pl.playerLicense AS text) AS playerId, COALESCE((SELECT geType.nameShort FROM gameEvent ge INNER JOIN participant p2 ON ge.participant=p2.guid INNER JOIN gameEventTypes geType ON ge.gameEventType=geType.id WHERE ge.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND p2.cap=:cap AND p2.number=p.number AND ge.gameEventType>=:exclTypeMin AND ge.gameEventType<=:exclTypeMax AND ge.deleted=0 AND p2.deleted=0 ORDER BY ge.gameSection DESC, ge.time ASC LIMIT 1), \"\") AS P1, COALESCE((SELECT geType.nameShort FROM gameEvent ge INNER JOIN participant p2 ON ge.participant=p2.guid INNER JOIN gameEventTypes geType ON ge.gameEventType=geType.id WHERE ge.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND p2.cap=:cap AND p2.number=p.number AND ge.gameEventType>=:exclTypeMin AND ge.gameEventType<=:exclTypeMax AND ge.deleted=0 AND p2.deleted=0 ORDER BY ge.gameSection DESC, ge.time ASC LIMIT 1 OFFSET 1), \"\") AS P2, COALESCE((SELECT geType.nameShort FROM gameEvent ge INNER JOIN participant p2 ON ge.participant=p2.guid INNER JOIN gameEventTypes geType ON ge.gameEventType=geType.id WHERE ge.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND p2.cap=:cap AND p2.number=p.number AND ge.gameEventType>=:exclTypeMin AND ge.gameEventType<=:exclTypeMax AND ge.deleted=0 AND p2.deleted=0 ORDER BY ge.gameSection DESC, ge.time ASC LIMIT 1 OFFSET 2), \"\") AS P3, CAST(COALESCE((SELECT COUNT(*) FROM gameEvent ge INNER JOIN participant p2 ON ge.participant=p2.guid WHERE ge.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND p2.cap=:cap AND p2.number=p.number AND ge.gameEventType>=:goalTypeMin AND ge.gameEventType<=:goalTypeMax AND ge.deleted=0 AND p2.deleted=0), 0) AS text) AS tore FROM participant p INNER JOIN player pl ON pl.guid=p.player WHERE p.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND p.cap=:cap AND p.deleted=0 AND pl.deleted=0 AND p.number>0 AND p.function IN (1,2,4,5) ORDER BY p.number"
    )
    fun getProtocolTeamWithPlayerId(cap: String, exclTypeMin: Int, exclTypeMax: Int, goalTypeMin: Int, goalTypeMax: Int): Flow<List<ProtocolTeam>>

    @RewriteQueriesToDropUnusedColumns
    @Query(
        "SELECT * FROM (SELECT 1 AS gameSection,\"I.   Viertel\" AS guid,1000000 AS time,\"\" AS numberWhite,\"\" AS numberBlue,\"\" AS type UNION ALL SELECT 2 AS gameSection,\"II.  Viertel\" AS guid,1000000 AS time,\"\" AS numberWhite,\"\" AS numberBlue,\"\" AS type UNION ALL SELECT 3 AS gameSection,\"III. Viertel\" AS guid,1000000 AS time,\"\" AS numberWhite,\"\" AS numberBlue,\"\" AS type UNION ALL SELECT 4 AS gameSection,\"IV. Viertel\" AS guid,1000000 AS time,\"\" AS numberWhite,\"\" AS numberBlue,\"\" AS type UNION ALL SELECT gameEvent.gameSection ,gameEvent.guid, gameEvent.time, CASE WHEN gameEvent.gameEventType=9 THEN CASE WHEN participant.cap=\"white\" THEN \"TO\" ELSE \"\" END WHEN participant.cap=\"white\" THEN CAST(participant.number AS text) ELSE \"\" END AS numberWhite,CASE WHEN gameEvent.gameEventType=9 THEN CASE WHEN participant.cap=\"blue\" THEN \"TO\" ELSE \"\" END WHEN participant.cap=\"blue\" THEN CAST(participant.number AS text) ELSE \"\" END AS numberBlue,CASE WHEN gameEvent.gameEventType=9 THEN \"TO\" ELSE CAST(gameEventTypes.nameShort AS text) END AS type FROM gameEvent INNER JOIN participant ON gameEvent.participant=participant.guid INNER JOIN gameEventTypes ON gameEventTypes.id=gameEvent.gameEventType WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND ((gameEventType>=:exclTypeMin AND gameEventType<=:exclTypeMax) OR gameEventType=9) AND gameEvent.deleted=0 AND participant.deleted=0 AND (participant.number>0 OR gameEvent.gameEventType=9)) ORDER BY gameSection,time DESC"
    )
    fun getProtocolOrderedByGameEventType(exclTypeMin: Int, exclTypeMax: Int): Flow<List<ProtocolGameEventType>>

    @RewriteQueriesToDropUnusedColumns
    @Query(
        "SELECT * FROM (SELECT 1 AS gameSection,\"I.   Viertel\" AS guid,1000000 AS time,\"\" AS numberWhite,\"\" AS numberBlue,\"\" AS type, \"\" AS goalWhite,\"\" AS goalBlue UNION ALL SELECT 2 AS gameSection,\"II.  Viertel\" AS guid,1000000 AS time,\"\" AS numberWhite,\"\" AS numberBlue,\"\" AS type, \"\" AS goalWhite,\"\" AS goalBlue UNION ALL SELECT 3 AS gameSection,\"III. Viertel\" AS guid,1000000 AS time,\"\" AS numberWhite,\"\" AS numberBlue,\"\" AS type, \"\" AS goalWhite,\"\" AS goalBlue UNION ALL SELECT 4 AS gameSection,\"IV. Viertel\" AS guid,1000000 AS time,\"\" AS numberWhite,\"\" AS numberBlue,\"\" AS type, \"\" AS goalWhite,\"\" AS goalBlue UNION ALL SELECT ge.gameSection ,ge.guid, ge.time, CASE WHEN participant.cap=\"white\" THEN CAST(participant.number AS text) ELSE \"\" END AS numberWhite,CASE WHEN participant.cap=\"blue\" THEN CAST(participant.number AS text) ELSE \"\" END AS numberBlue,CAST(gameEventTypes.nameShort AS text) AS type, COALESCE((SELECT COUNT(*) FROM gameEvent geInner INNER JOIN  participant pa  ON geInner.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND geInner.participant=pa.guid WHERE ((geInner.gameSection<ge.gameSection) OR (geInner.gameSection=ge.gameSection AND geInner.time>=ge.time)) AND geInner.gameEventType>=:goalTypeMin AND geInner.gameEventType<=:goalTypeMax AND pa.cap=\"white\" AND geInner.deleted=0 AND pa.deleted=0 AND pa.number>0 ORDER BY geInner.gameSection,geInner.time DESC),\"0\") AS goalWhite, COALESCE((SELECT COUNT(*) FROM gameEvent geInner INNER JOIN  participant pa  ON geInner.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND geInner.participant=pa.guid WHERE ((geInner.gameSection<ge.gameSection) OR (geInner.gameSection=ge.gameSection AND geInner.time>=ge.time)) AND geInner.gameEventType>=:goalTypeMin AND geInner.gameEventType<=:goalTypeMax AND pa.cap=\"blue\" AND geInner.deleted=0 AND pa.deleted=0 AND pa.number>0 ORDER BY geInner.gameSection,geInner.time DESC),\"0\")AS goalBlue FROM gameEvent ge INNER JOIN participant ON ge.participant=participant.guid INNER JOIN gameEventTypes ON gameEventTypes.id=ge.gameEventType WHERE ge.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND gameEventType>=100 AND gameEventType<=199 AND ge.deleted=0 AND participant.deleted=0 AND participant.number>0) ORDER BY gameSection,time DESC"
    )
    fun getProtocolOrderedByGoals(goalTypeMin: Int, goalTypeMax: Int): Flow<List<ProtocolGoalType>>

    @Query("SELECT SUM(resultWhite) AS white,SUM(resultBlue) AS blue FROM (SELECT COUNT(*) AS resultWhite, 0 AS resultBlue FROM gameEvent INNER JOIN participant ON gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND participant.cap=\"white\" AND gameEvent.participant=participant.guid WHERE gameEvent.gameEventType>=:goalTypeMin AND gameEvent.gameEventType<=:goalTypeMax AND gameEvent.gameSection IN (:gameSection) AND NOT gameEvent.deleted AND participant.number>0 UNION ALL SELECT 0 AS resultWhite, COUNT(*) AS resultBlue FROM gameEvent INNER JOIN participant ON gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND participant.cap=\"blue\" AND gameEvent.participant=participant.guid WHERE gameEvent.gameEventType>=:goalTypeMin AND gameEvent.gameEventType<=:goalTypeMax AND gameEvent.gameSection IN (:gameSection) AND NOT gameEvent.deleted AND participant.number>0)")
    fun getResult(goalTypeMin: Int, goalTypeMax: Int, gameSection: IntArray): Flow<GameResult>

    @Query(
        "SELECT COALESCE((SELECT nameShort FROM gameEvent gameEvent INNER JOIN participant ON gameEvent.participant=participant.guid INNER JOIN gameEventTypes ON gameEvent.gameEventType=gameEventTypes.id WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND participant.cap=:cap AND participant.number=:number AND gameEvent.gameEventType>=:exclTypeMin AND gameEvent.gameEventType<=:exclTypeMax AND gameEvent.deleted=0 AND participant.deleted=0 ORDER BY gameSection,time DESC LIMIT 1),\"\") AS e1, COALESCE((SELECT nameShort FROM gameEvent gameEvent INNER JOIN participant ON gameEvent.participant=participant.guid INNER JOIN gameEventTypes ON gameEvent.gameEventType=gameEventTypes.id WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND participant.cap=:cap AND participant.number=:number AND gameEvent.gameEventType>=:exclTypeMin AND gameEvent.gameEventType<=:exclTypeMax AND gameEvent.deleted=0 AND participant.deleted=0 ORDER BY gameSection,time DESC LIMIT 1 OFFSET 1),\"\") AS e2,COALESCE((SELECT nameShort FROM gameEvent gameEvent INNER JOIN participant ON gameEvent.participant=participant.guid INNER JOIN gameEventTypes ON gameEvent.gameEventType=gameEventTypes.id WHERE gameEvent.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND participant.cap=:cap AND participant.number=:number AND gameEvent.gameEventType>=:exclTypeMin AND gameEvent.gameEventType<=:exclTypeMax AND gameEvent.deleted=0 AND participant.deleted=0 AND participant.number>0 ORDER BY gameSection,time DESC LIMIT 1 OFFSET 2),\"\") AS e3"
    )
    fun getExclusionByPlayer(cap: String, number: Int, exclTypeMin: Int, exclTypeMax: Int): Flow<ExclResult>

    @Query("SELECT :cap AS cap,number,playerFirstName,playerLastName,player.guid FROM player INNER JOIN participant ON player.guid=participant.player WHERE participant.cap=:cap AND participant.game=(SELECT guid FROM game ORDER BY created DESC LIMIT 1) AND participant.deleted=0 AND participant.function in (1,2,4,5) AND participant.number>0 ")
    fun getNamesPlayer(cap: String): Flow<List<EditTeam>>
}